main.script:
        
(function () {
    function hasClass(node, className) {
        return node.className && (" " + node.className + " ").indexOf(" " + className + " ") >= 0;
    }

    function wrapTextNode(textNode) {
        var text = textNode.nodeValue;

        if (!text || !text.replace(/\s+/g, "")) {
            return;
        }

        /* إزالة أي كشيدة موجودة فعليًا في النص */
        text = text.replace(/\u0640/g, "");

        var parts = text.split(/(\s+)/);
        var frag = document.createDocumentFragment();

        for (var i = 0; i < parts.length; i++) {
            var part = parts[i];

            if (!part) {
                continue;
            }

            if (/^\s+$/.test(part)) {
                frag.appendChild(document.createTextNode(part));
            } else {
                var span = document.createElement("span");
                span.className = "ar-word";
                span.appendChild(document.createTextNode(part));
                frag.appendChild(span);
            }
        }

        textNode.parentNode.replaceChild(frag, textNode);
    }

    function walk(node) {
        if (node.nodeType === 3) {
            wrapTextNode(node);
            return;
        }

        if (node.nodeType !== 1) {
            return;
        }

        var tag = node.tagName.toLowerCase();

        if (
            tag === "script" ||
            tag === "style" ||
            tag === "img" ||
            tag === "svg" ||
            tag === "br" ||
            hasClass(node, "ar-word") ||
            hasClass(node, "icon-saudi_riyal")
        ) {
            return;
        }

        var children = [];
        for (var i = 0; i < node.childNodes.length; i++) {
            children.push(node.childNodes[i]);
        }

        for (var j = 0; j < children.length; j++) {
            walk(children[j]);
        }
    }

    function runArabicJustifyFix() {
        var elements = document.querySelectorAll(
            ".contract-paragraph, .contract-paragraph1, .audit-bullet-text"
        );

        for (var i = 0; i < elements.length; i++) {
            if (elements[i].getAttribute("data-no-auto-justify") === "1") {
                continue;
            }

            elements[i].className += " ar-auto-justify";
            walk(elements[i]);
        }
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", runArabicJustifyFix);
    } else {
        runArabicJustifyFix();
    }
})();
